def buggy(intervals):
    intervals = sorted(intervals)
    merged = [list(intervals[0])]
    for start, end in intervals[1:]:
        if start < merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [tuple(p) for p in merged]

example = find_counterexample(buggy)
assert example is not None, "found nothing, but agent_merge has two bugs"
try:
    problems = violations(example, buggy(example))
except Exception as e:
    problems = [f"raises {type(e).__name__}"]
assert problems, f"{example} is not a counterexample: the agent's code handles it correctly"
print("counterexample:", example, "->", problems[0])

import random

def reference(intervals):
    out = []
    for s, e in sorted(intervals):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return [tuple(p) for p in out]

rng = random.Random(42)
for _ in range(400):
    xs = []
    for _ in range(rng.randint(0, 7)):
        a = rng.randint(0, 20)
        xs.append((a, a + rng.randint(0, 6)))
    got = merge(list(xs))
    assert got == reference(xs), f"merge({xs}) returned {got}, expected {reference(xs)}"
